static uint16_t u16(const unsigned char*p){return (uint16_t)(p[0]|p[1]<<8);}
static uint32_t u32(const unsigned char*p){return (uint32_t)p[0]|(uint32_t)p[1]<<8|(uint32_t)p[2]<<16|(uint32_t)p[3]<<24;}
static uint32_t crc32raw(const unsigned char*p,size_t n){uint32_t c=0xffffffffU;size_t i;int j;for(i=0;i<n;i++){c^=p[i];for(j=0;j<8;j++)c=(c>>1)^((c&1)?0xedb88320U:0);}return c^0xffffffffU;}
typedef struct { wchar_t path[1024];HANDLE file;unsigned char*central;size_t centralSize;int directory; } Mount;
static Mount mounts[MAX_MOUNTS];static int mountCount;static wchar_t rootDir[1024];static CRITICAL_SECTION lock;static volatile LONG lockReady,initialized;
static void ensureLock(void){if(InterlockedCompareExchange(&lockReady,1,0)==0){InitializeCriticalSection(&lock);InterlockedExchange(&lockReady,2);}else while(lockReady!=2)Sleep(0);}
static int fileSize64(HANDLE f,LARGE_INTEGER*out){DWORD hi=0,lo;SetLastError(0);lo=GetFileSize(f,&hi);if(lo==0xffffffffU&&GetLastError()!=0)return 0;out->QuadPart=((uint64_t)hi<<32)|lo;return 1;}
