void GameAudioSetRoot(const wchar_t*root){int i;ensureLock();EnterCriticalSection(&lock);for(i=0;i<mountCount;i++){if(mounts[i].central)HeapFree(GetProcessHeap(),0,mounts[i].central);if(!mounts[i].directory&&mounts[i].file!=INVALID_HANDLE_VALUE)CloseHandle(mounts[i].file);}mountCount=0;initialized=0;wcsncpy(rootDir,root,1023);rootDir[1023]=0;LeaveCriticalSection(&lock);}
